# OWASP LLM Top 10: safety gate for a tool-using AI feature.
request = {"action": "issue_refund", "has_user_confirmation": False, "contains_sensitive_data": True, "audit_log": True}

def decision(req):
    if req["action"] == "issue_refund" and not req["has_user_confirmation"]:
        return "block"
    if req["contains_sensitive_data"] and not req["audit_log"]:
        return "block"
    return "allow"

print(decision(request))
print("human review" if decision(request) == "block" else "continue")
